    func testCancelledGroupDirectoryRefreshCannotAffectCurrentSession() async throws {
        let transport = FakeHTTPTransport(
            results: [
                HTTPTransportResult(
                    data: Data(#"{"ok":false,"error":{"code":"unauthorized"}}"#.utf8),
                    isHTTPResponse: true,
                    statusCode: 401
                )
            ],
            delayNanoseconds: 1_000_000_000
        )
        let state = AppState(
            api: makeClient(transport: transport),
            conversationStore: ConversationStore(),
            apiContextOverride: makeContext()
        )
        state.isAuthenticated = true
        let refresh = Task { await state.refreshGroupDirectory(silent: false) }
        try await waitForCondition { transport.requests().count == 1 }

        refresh.cancel()

        let refreshSucceeded = await refresh.value
        XCTAssertFalse(refreshSucceeded)
        XCTAssertTrue(state.isAuthenticated)
        XCTAssertNil(state.toast)
    }

