            XCTAssertEqual(sends.count, 1, scene)
            let body = try requestJSONObject(XCTUnwrap(sends.first))
            XCTAssertEqual(body["app_id"] as? String, state.currentAppID)
            XCTAssertEqual(body["scene"] as? String, scene)
        }
    }

