        let imBase = try XCTUnwrap(IMAPIClient.normalizedIMAPIBaseURL(enter.runtimeConfig.imAPIBaseURL))
        let session = try await client.platformEntry(
            entryTicket: enter.entryTicket,
            tenantBaseURL: tenantBase,
