                isHTTPResponse: true,
                statusCode: 401
            ),
            HTTPTransportResult(
                data: Data(#"{"ok":true,"data":{"entry_ticket":"entry-ticket-test","runtime_config":{"tenant_api_base_url":"https://tenant.example.test","tenant_api_base_url_source":"tenant_deployment_config","tenant_api_base_url_configured":true,"im_api_base_url":"https://im.example.test"}}}"#.utf8),
                isHTTPResponse: true,
                statusCode: 200
            ),
            HTTPTransportResult(
                data: Data(#"{"ok":true,"data":{"tenant":{"tenant_id":"tenant-1","name":"Local Tenant","tenant_code":"WXT000001","status":"active"},"member":{"tenant_id":"tenant-1","account_id":"account-1","im_uid":"uid-1","status":"active","role":"member"},"im_uid":"uid-1","im_token":"im-token-new","app_id":"jianhuitong-ios","device_id":"device-1","auth_session":{"session_id":"tenant-session-1","refresh_token":"tenant-refresh-1","expires_at":1785200000,"tenant_id":"tenant-1","app_id":"jianhuitong-ios","device_id":"device-1","client_type":"ios","token_type":"im"}}}"#.utf8),
                isHTTPResponse: true,
                statusCode: 200
            )
        ])
        let state = AppState(api: makeClient(transport: transport), apiContextOverride: context)
        let enterprise = Enterprise(
            id: "tenant-1",
            name: "Local Tenant",
            code: "WXT000001",
            role: "member",
            status: "active",
            memberCount: 1,
            isDefault: true,
